rules.logic:
if (element.querySelector('.global-en-resources')) return;

var queryInput = document.querySelector('.HeaderForm-Input');
var query = queryInput ? queryInput.value.trim() : '';
if (!query) return;

var encodedQuery = encodeURIComponent(query);

var resources = [
  { name: 'Wikipedia', url: 'https://en.wikipedia.org/wiki/Special:Search?search=' + encodedQuery, desc: 'The free encyclopedia', icon: '📚' },
  { name: 'Medium', url: 'https://medium.com/search?q=' + encodedQuery, desc: 'Reading & sharing platform', icon: '✍️' },
  { name: 'LinkedIn', url: 'https://www.linkedin.com/search/results/all/?keywords=' + encodedQuery, desc: 'Professional network', icon: '💼' }
];

var container = document.createElement('div');
container.className = 'global-en-resources';
container.style.cssText = 'padding:12px 0;margin-bottom:8px;border-bottom:1px solid #e0e0e0;';

var header = document.createElement('div');
header.style.cssText = 'font-size:13px;color:#888;margin-bottom:8px;font-weight:500;padding-left:4px;';
header.textContent = 'Global English-language resources:';
container.appendChild(header);

var row = document.createElement('div');
row.style.cssText = 'display:flex;gap:12px;flex-wrap:wrap;';

resources.forEach(function(r) {
  var card = document.createElement('a');
  card.href = r.url;
  card.target = '_blank';
  card.rel = 'noopener noreferrer';
  card.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 16px;border-radius:12px;background:#f5f7fa;text-decoration:none;border:1px solid #e8ecf0;min-width:200px;flex:1;transition:background 0.15s,box-shadow 0.15s;';
  card.onmouseover = function() { this.style.background = '#eef2f7'; this.style.boxShadow = '0 2px 8px rgba(0,0,0,0.08)'; };
  card.onmouseout = function() { this.style.background = '#f5f7fa'; this.style.boxShadow = 'none'; };

  var iconSpan = document.createElement('span');
  iconSpan.style.cssText = 'font-size:22px;line-height:1;';
  iconSpan.textContent = r.icon;
  card.appendChild(iconSpan);

  var textBlock = document.createElement('div');
  textBlock.style.cssText = 'display:flex;flex-direction:column;';

  var nameEl = document.createElement('span');
  nameEl.style.cssText = 'font-size:14px;font-weight:600;color:#333;line-height:1.3;';
  nameEl.textContent = r.name;
  textBlock.appendChild(nameEl);

  var descEl = document.createElement('span');
  descEl.style.cssText = 'font-size:12px;color:#888;line-height:1.3;';
  descEl.textContent = r.desc;
  textBlock.appendChild(descEl);

  card.appendChild(textBlock);
  row.appendChild(card);
});

container.appendChild(row);
element.appendChild(container);

